function makeTaskCounter(name, start) {
  let number = start;
  return function () {
    number += 1;
    return `${name} 작업 ${number}`;
  };
}
function runTaskCounter(name, start) {
  const next = makeTaskCounter(name, start);
  return { first: next(), second: next(), third: next() };
}
